//! D-Bus object for the zeroclaw Axum host.
//!
//! Exposes `/org/opdbus/v1/services/zeroclaw_axum_host` with the runtime
//! configuration properties required by the spec. Writes to `BindAddr` or
//! `SchemaPath` trigger a reload signal; the server task picks it up and
//! reconfigures without restarting the process.

use std::sync::Arc;

use tokio::sync::{mpsc, RwLock};
use tracing::{info, warn};

use crate::schema_loader::SchemaLoader;

const DEFAULT_BIND_ADDR: &str = "0.0.0.0:8090";

/// D-Bus-facing configuration object for the zeroclaw Axum host.
#[derive(Clone)]
pub struct ZeroclawAxumHostObject {
    bind_addr: Arc<RwLock<String>>,
    schema_path: Arc<RwLock<String>>,
    reload_interval_secs: Arc<RwLock<u32>>,
    loader: Arc<SchemaLoader>,
    rebind_tx: mpsc::Sender<String>,
}

impl ZeroclawAxumHostObject {
    pub fn new(loader: Arc<SchemaLoader>, rebind_tx: mpsc::Sender<String>) -> anyhow::Result<Self> {
        let initial_path = loader.path().to_string_lossy().to_string();
        Ok(Self {
            bind_addr: Arc::new(RwLock::new(DEFAULT_BIND_ADDR.to_string())),
            schema_path: Arc::new(RwLock::new(initial_path)),
            reload_interval_secs: Arc::new(RwLock::new(0)),
            loader,
            rebind_tx,
        })
    }

    /// Read the current TCP bind address.
    async fn bind_addr_value(&self) -> String {
        self.bind_addr.read().await.clone()
    }

    /// Read the current plugin-owned schema file path.
    async fn schema_path_value(&self) -> String {
        self.schema_path.read().await.clone()
    }

    /// Read the current periodic reload interval in seconds.
    async fn reload_interval_value(&self) -> u32 {
        *self.reload_interval_secs.read().await
    }
}

#[zbus::interface(name = "org.opdbus.v1.ZeroclawAxumHost")]
impl ZeroclawAxumHostObject {
    #[zbus(property)]
    async fn bind_addr(&self) -> String {
        self.bind_addr_value().await
    }

    #[zbus(property)]
    async fn set_bind_addr(&self, value: String) {
        let mut addr = self.bind_addr.write().await;
        *addr = value.clone();
        drop(addr);
        info!(subid = "mut.service.zeroclaw-axum-host.reload@v1", new_bind = %value, "BindAddr changed; signaling rebind");
        if let Err(e) = self.rebind_tx.send(value).await {
            warn!(error = %e, "failed to send rebind request");
        }
    }

    #[zbus(property)]
    async fn schema_path(&self) -> String {
        self.schema_path_value().await
    }

    #[zbus(property)]
    async fn set_schema_path(&self, value: String) {
        let mut path = self.schema_path.write().await;
        *path = value.clone();
        drop(path);
        self.loader.set_path(value.clone());
        info!(subid = "mut.service.zeroclaw-axum-host.reload@v1", new_path = %value, "SchemaPath changed; reloading");
        if let Err(e) = self.loader.reload().await {
            warn!(error = %e, "schema path reload failed");
            self.loader.set_health_status(e.to_string()).await;
        }
    }

    #[zbus(property)]
    async fn reload_interval_secs(&self) -> u32 {
        self.reload_interval_value().await
    }

    #[zbus(property)]
    async fn set_reload_interval_secs(&self, value: u32) {
        let mut interval = self.reload_interval_secs.write().await;
        *interval = value;
    }

    #[zbus(property)]
    async fn health_status(&self) -> String {
        self.loader.health_status().await
    }
}

/// Register the zeroclaw Axum host object on the system bus.
pub async fn register_zeroclaw_host_object(
    object: ZeroclawAxumHostObject,
) -> anyhow::Result<zbus::Connection> {
    let connection = zbus::Connection::system().await?;
    connection
        .object_server()
        .at("/org/opdbus/v1/services/zeroclaw_axum_host", object)
        .await?;
    info!("registered /org/opdbus/v1/services/zeroclaw_axum_host");
    Ok(connection)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn should_expose_dbus_properties() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("zeroclaw.json");
        std::fs::write(&path, r#"{"name":"zeroclaw"}"#).unwrap();

        let loader = Arc::new(SchemaLoader::new(&path).unwrap());
        let (rebind_tx, _rebind_rx) = mpsc::channel(1);
        let obj = ZeroclawAxumHostObject::new(loader, rebind_tx).unwrap();

        assert_eq!(obj.bind_addr_value().await, "0.0.0.0:8090");
        assert_eq!(obj.schema_path_value().await, path.to_string_lossy());
        assert_eq!(obj.reload_interval_value().await, 0);
        assert_eq!(obj.health_status().await, "ok");
    }
}

//! D-Bus object server for projections.
//!
//! Serves every Projection through org.opdbus.v1.plugins at
//! /org/opdbus/v1/plugins/<plugin>. Nothing mounts outside the plugins root:
//! no plugin means no schema means no object.
//!
//! Data is read 1:1 from the shared-memory projection layer
//! (`/dev/shm/opdbus/projections/<plugin>.json`) on every property access.
//! No held cache — the projected tree is a pure read-through of the mutation
//! fold written by the MutationEngine (the single write door).
//!
//! Tree structure is derived on-demand: the `ProjectionRoot` interface at
//! `/org/opdbus/v1/plugins` exposes a `refresh()` D-Bus method that re-reads
//! shm and mounts/unmounts objects to match. No gRPC subscription, no polling,
//! no inotify — the tree syncs when asked.

use anyhow::Result;
use std::collections::HashSet;
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{debug, info, warn};
use zbus::{connection::Builder, interface, object_server::SignalEmitter, Connection};

/// A single projected object on the D-Bus object server.
///
/// Reads its data 1:1 from the shm projection layer on every property access.
/// No held cache — the mutation fold in `/dev/shm/opdbus/projections/` is the
/// single source of truth, written by the MutationEngine on every mutation.
pub struct ProjectedObject {
    /// The plugin that owns this object (e.g. "wireguard").
    pub plugin_id: String,
    /// Path segments below the plugin root (empty for the plugin root itself).
    /// e.g. `["interfaces", "0", "peers"]` for
    /// `/org/opdbus/v1/plugins/wireguard/interfaces/0/peers`
    pub path_segments: Vec<String>,
}

#[interface(name = "org.opdbus.v1.plugins.ProjectedObject")]
impl ProjectedObject {
    /// The schema/entity type for this object (plugin id for roots, "plugin.object" for nested)
    #[zbus(property)]
    async fn entity_type(&self) -> String {
        if self.path_segments.is_empty() {
            self.plugin_id.clone()
        } else {
            "plugin.object".to_string()
        }
    }

    /// The unique entity ID within its type
    #[zbus(property)]
    async fn entity_id(&self) -> String {
        if self.path_segments.is_empty() {
            self.plugin_id.clone()
        } else {
            format!("{}:/{}", self.plugin_id, self.path_segments.join("/"))
        }
    }

    /// Current projection state: always Valid (1:1 read of canonical state).
    #[zbus(property)]
    async fn state(&self) -> String {
        "Valid".to_string()
    }

    /// Full projection data as a JSON string, read 1:1 from shm.
    #[zbus(property)]
    async fn data(&self) -> String {
        read_projected_data(&self.plugin_id, &self.path_segments)
    }

    /// Signal emitted when this object's data changes
    #[zbus(signal)]
    async fn updated(emitter: &SignalEmitter<'_>, data_json: &str) -> zbus::Result<()>;
}

/// Read projected data for a plugin/path from the shm layer (1:1, zero held cache).
///
/// For the plugin root (empty `path_segments`), returns the `data` field from
/// the composite shm object (or the raw file if not a composite).
/// For nested objects, parses the JSON, navigates to the path within `data`,
/// and re-serializes.
fn read_projected_data(plugin_id: &str, path_segments: &[String]) -> String {
    let bytes = match op_core::projection_shm::read_projection_bytes(plugin_id) {
        Some(b) => b,
        None => return "{}".to_string(),
    };
    let value: serde_json::Value = match serde_json::from_slice(&bytes) {
        Ok(v) => v,
        Err(_) => return "{}".to_string(),
    };

    // Navigate from the `data` field if present (composite shm format).
    let root = value.get("data").unwrap_or(&value);

    if path_segments.is_empty() {
        serde_json::to_string(root).unwrap_or_else(|_| "{}".to_string())
    } else {
        match navigate_json(root, path_segments) {
            Some(v) => serde_json::to_string(v).unwrap_or_else(|_| "{}".to_string()),
            None => "{}".to_string(),
        }
    }
}

/// Navigate a JSON value by path segments (object keys or array indices).
fn navigate_json<'a>(
    value: &'a serde_json::Value,
    segments: &[String],
) -> Option<&'a serde_json::Value> {
    let mut current = value;
    for segment in segments {
        current = if let Ok(idx) = segment.parse::<usize>() {
            current.get(idx)?
        } else {
            current.get(segment.as_str())?
        };
    }
    Some(current)
}

/// Derives the D-Bus object path from a projection's entity_type and entity_id.
///
/// Every projected object lives under the single plugins root, and nested
/// objects live under the plugin that produced them. No plugin means no schema
/// means no object — nothing is ever mounted outside this path.
///
/// entity_type "mail_server", entity_id "mail_server"
///   → /org/opdbus/v1/plugins/mail_server
/// entity_type "plugin.object", entity_id "wireguard:/interfaces/0"
///   → /org/opdbus/v1/plugins/wireguard/interfaces/0
pub fn projection_path(entity_type: &str, entity_id: &str) -> String {
    if entity_type == "plugin.object" {
        if let Some((plugin_id, object_path)) = entity_id.split_once(':') {
            return plugin_object_path(plugin_id, object_path);
        }
    }

    op_plugins::canonical::plugin_path(if entity_id.is_empty() {
        entity_type
    } else {
        entity_id
    })
}

fn plugin_object_path(plugin_id: &str, object_path: &str) -> String {
    let mut path = op_plugins::canonical::plugin_path(plugin_id);

    for segment in object_path.split('/').filter(|segment| !segment.is_empty()) {
        path.push('/');
        path.push_str(&sanitize_path_segment(segment));
    }

    path
}

fn sanitize_path_segment(segment: &str) -> String {
    let sanitized: String = segment
        .chars()
        .filter_map(|c| {
            if c.is_ascii_alphanumeric() || c == '_' {
                Some(c)
            } else if c == '-' || c == '.' {
                Some('_')
            } else {
                None
            }
        })
        .take(255)
        .collect();

    if sanitized.is_empty() {
        "_".to_string()
    } else {
        sanitized
    }
}

/// Build the D-Bus object path from a plugin id and path segments.
fn build_projected_path(plugin_id: &str, path_segments: &[String]) -> String {
    let mut path = format!(
        "{}/{}",
        op_plugins::canonical::PLUGIN_BASE_PATH,
        sanitize_path_segment(plugin_id)
    );
    for seg in path_segments {
        path.push('/');
        path.push_str(&sanitize_path_segment(seg));
    }
    path
}

/// Root interface at `/org/opdbus/v1/plugins`.
///
/// Always present so D-Bus introspection works even with zero plugins mounted.
/// The `plugins` property reads shm live. The `refresh()` method re-reads shm
/// and syncs the D-Bus tree (mount/unmount objects to match). This is the
/// dynamic-mount mechanism: no gRPC, no polling, no inotify — the tree is
/// derived on demand.
pub struct ProjectionRoot {
    objects: Arc<Mutex<HashSet<String>>>,
}

#[interface(name = "org.opdbus.v1.plugins.ProjectionRoot")]
impl ProjectionRoot {
    /// List of plugin IDs currently projected in shm (live read).
    #[zbus(property)]
    async fn plugins(&self) -> Vec<String> {
        op_core::projection_shm::list_projected_plugins()
    }

    /// Number of D-Bus objects currently mounted.
    #[zbus(property)]
    async fn object_count(&self) -> u64 {
        self.objects.lock().await.len() as u64
    }

    /// Re-read shm and sync the D-Bus tree. Mounts new objects, unmounts stale
    /// ones. Returns the total object count after refresh.
    ///
    /// Call this after a mutation has written new state to shm. The
    /// MutationEngine can call this via D-Bus after writing to shm, or any
    /// client can call it to force a tree refresh.
    async fn refresh(&self, #[zbus(connection)] conn: &Connection) -> u64 {
        let mut objects = self.objects.lock().await;
        match sync_all_from_shm(conn, &mut objects).await {
            Ok(()) => objects.len() as u64,
            Err(e) => {
                tracing::warn!(error = %e, "refresh() failed");
                objects.len() as u64
            }
        }
    }
}

/// Default gRPC endpoint of the bridge's `PluginService` — the MutationEngine,
/// the single write door (the gated `run_grpc_server` :50051 surface). Sourced
/// from `OP_DBUS_GRPC_ADDR` (the canonical env in /etc/op-dbus/environment),
/// then `OPDBUS_PLUGIN_GRPC`, falling back to the WG host endpoint.
const DEFAULT_PLUGIN_GRPC_ENDPOINT: &str = "https://10.200.0.1:50051";

fn plugin_grpc_endpoint() -> String {
    std::env::var("OPDBUS_PLUGIN_GRPC")
        .or_else(|_| std::env::var("OP_DBUS_GRPC_ADDR"))
        .unwrap_or_else(|_| DEFAULT_PLUGIN_GRPC_ENDPOINT.to_string())
}

/// Writable D-Bus interface for the `unix_socket` plugin object, served on the
/// system bus at `/org/opdbus/v1/plugins/unix_socket` (local agents / scripts /
/// `zbusctl` — the session bus is the WG-identity-gated container surface).
///
/// It never writes shm directly: `createunixsocket` is forwarded to the bridge's
/// `PluginService.CallMethod`, which dispatches in the MutationEngine (the single
/// write door) so the registration is recorded on the mutation chain. This keeps
/// the only-valid-path rule (`org.opdbus.v1.plugins.<plugin>`) and the
/// single-writer invariant intact.
pub struct UnixSocketMethods {
    grpc_endpoint: String,
}

impl UnixSocketMethods {
    pub fn new() -> Self {
        Self {
            grpc_endpoint: plugin_grpc_endpoint(),
        }
    }
}

impl Default for UnixSocketMethods {
    fn default() -> Self {
        Self::new()
    }
}

#[interface(name = "org.opdbus.v1.plugins.unix_socket")]
impl UnixSocketMethods {
    /// Register a container/service routing tag on the shared `container.sock`
    /// transport. `ports` is required (the backend port(s) the container serves);
    /// an empty list is rejected. Routes through the MutationEngine and returns
    /// the resulting mutation event hash.
    async fn createunixsocket(&self, name: String, ports: Vec<u16>) -> zbus::fdo::Result<String> {
        if name.is_empty() {
            return Err(zbus::fdo::Error::InvalidArgs("name is required".into()));
        }
        if ports.is_empty() {
            return Err(zbus::fdo::Error::InvalidArgs(
                "at least one port is required".into(),
            ));
        }
        create_unix_socket_via_bridge(&self.grpc_endpoint, name, ports)
            .await
            .map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }
}

/// Mount the `unix_socket` plugin's writable `createunixsocket` method at its
/// object path. The read-only `ProjectedObject` is added later by seed/sync at
/// the same path; zbus serves both interfaces on the one node.
async fn mount_unix_socket_methods(conn: &Connection) {
    let path = build_projected_path("unix_socket", &[]);
    match conn
        .object_server()
        .at(path.as_str(), UnixSocketMethods::new())
        .await
    {
        Ok(_) => debug!(path, "Mounted unix_socket createunixsocket D-Bus method"),
        Err(e) => warn!(error = %e, path, "failed to mount unix_socket createunixsocket method"),
    }
}

/// Forward `createunixsocket` to the bridge's `PluginService.CallMethod`. The
/// MutationEngine parses `[name, [ports]]` (see `parse_socket_args`), runs
/// `create_unix_socket`, and records the mutation. Returns the event hash.
async fn create_unix_socket_via_bridge(
    endpoint: &str,
    name: String,
    ports: Vec<u16>,
) -> anyhow::Result<String> {
    use op_grpc_bridge::proto::{plugin_service_client::PluginServiceClient, CallMethodRequest};
    use prost_types::{value::Kind, ListValue, Value as ProstValue};

    let port_values = ports
        .iter()
        .map(|p| ProstValue {
            kind: Some(Kind::NumberValue(*p as f64)),
        })
        .collect();
    let arguments = vec![
        ProstValue {
            kind: Some(Kind::StringValue(name.clone())),
        },
        ProstValue {
            kind: Some(Kind::ListValue(ListValue {
                values: port_values,
            })),
        },
    ];

    let mut request = tonic::Request::new(CallMethodRequest {
        plugin_id: "unix_socket".to_string(),
        object_path: build_projected_path("unix_socket", &[]),
        interface_name: "org.opdbus.v1.plugins.unix_socket".to_string(),
        method_name: "createunixsocket".to_string(),
        arguments,
        actor_id: "system-bus".to_string(),
        capability_id: String::new(),
    });

    // The gated PluginService (:50051) requires the Ghostbridge identity sled.
    // Read the live sled from shm and stamp the footprint + trace-id headers the
    // interceptor validates 1:1 against that same sled (see ghostbridge_interceptor).
    {
        let (sled_ptr, _mmap) =
            op_identity::read_sled().map_err(|e| anyhow::anyhow!("read identity sled: {e}"))?;
        let sled = unsafe { &*sled_ptr };
        let footprint = hex::encode(sled.hashed_footprint);
        let trace_id = sled.trace_id_hex();
        let md = request.metadata_mut();
        md.insert(
            "x-ghostbridge-footprint",
            footprint
                .parse()
                .map_err(|e| anyhow::anyhow!("footprint header: {e}"))?,
        );
        md.insert(
            "x-ghostbridge-trace-id",
            trace_id
                .parse()
                .map_err(|e| anyhow::anyhow!("trace-id header: {e}"))?,
        );
    }

    // TLS mandatory — the shared helper normalises http→https and applies the
    // client TLS config (LE *.ghostbridge.tech cert, webpki roots for verify).
    let endpoint_builder = op_grpc_bridge::tls::tls_endpoint(endpoint)
        .map_err(|e| anyhow::anyhow!("TLS endpoint for {endpoint}: {e}"))?;
    let channel = endpoint_builder
        .connect()
        .await
        .map_err(|e| anyhow::anyhow!("connect {endpoint}: {e}"))?;
    let mut client = PluginServiceClient::new(channel);
    let resp = client
        .call_method(request)
        .await
        .map_err(|e| anyhow::anyhow!("PluginService.CallMethod: {e}"))?
        .into_inner();

    if !resp.success {
        anyhow::bail!(resp
            .error
            .map(|e| e.message)
            .unwrap_or_else(|| "createunixsocket failed".to_string()));
    }
    Ok(format!("registered '{name}' (event {})", resp.event_hash))
}

/// Read all plugins from shm, derive paths, and sync the D-Bus tree.
///
/// For each plugin in shm, derives all nested object paths from the JSON
/// structure and mounts/unmounts `ProjectedObject` instances to match.
/// Plugins that are in shm but not yet mounted are added; objects that are
/// mounted but no longer in shm are removed.
async fn sync_all_from_shm(conn: &Connection, objects: &mut HashSet<String>) -> Result<()> {
    let plugins = op_core::projection_shm::list_projected_plugins();

    // Unmount plugins that are no longer in shm.
    let plugin_root_base = op_plugins::canonical::plugin_path("");
    let _ = plugin_root_base; // path prefix helper

    let to_remove: Vec<String> = objects
        .iter()
        .filter(|p| {
            // Keep only paths whose plugin is still in shm
            let parts: Vec<&str> = p.trim_start_matches('/').split('/').collect();
            if parts.len() >= 5
                && parts[0] == "org"
                && parts[1] == "opdbus"
                && parts[2] == "v1"
                && parts[3] == "plugins"
            {
                let plugin_id = parts[4];
                !plugins.iter().any(|p| p.as_str() == plugin_id)
            } else {
                false
            }
        })
        .cloned()
        .collect();

    for path in to_remove {
        if objects.remove(&path) {
            conn.object_server()
                .remove::<ProjectedObject, _>(path.as_str())
                .await?;
            debug!(
                path,
                "Unmounted stale D-Bus projection object (plugin gone from shm)"
            );
        }
    }

    // Mount/sync all plugins currently in shm.
    for plugin_id in &plugins {
        if let Some(paths) = read_and_derive_paths(plugin_id) {
            sync_plugin_paths(conn, objects, plugin_id, &paths).await?;
        }
    }

    Ok(())
}

/// Sync a single plugin's D-Bus objects to match the derived paths.
async fn sync_plugin_paths(
    conn: &Connection,
    objects: &mut HashSet<String>,
    plugin_id: &str,
    paths: &[Vec<String>],
) -> Result<()> {
    let new_paths: HashSet<String> = paths
        .iter()
        .map(|segs| build_projected_path(plugin_id, segs))
        .collect();

    let plugin_root = op_plugins::canonical::plugin_path(plugin_id);
    let plugin_prefix = format!("{}/", plugin_root);

    // Unmount paths that no longer exist in the derived set.
    let to_remove: Vec<String> = objects
        .iter()
        .filter(|p| {
            (**p == plugin_root || p.starts_with(&plugin_prefix)) && !new_paths.contains(*p)
        })
        .cloned()
        .collect();

    for path in to_remove {
        if objects.remove(&path) {
            conn.object_server()
                .remove::<ProjectedObject, _>(path.as_str())
                .await?;
            debug!(path, "Unmounted stale D-Bus projection object");
        }
    }

    // Mount all current paths.
    for segs in paths {
        let path = build_projected_path(plugin_id, segs);
        if !objects.contains(&path) {
            let obj = ProjectedObject {
                plugin_id: plugin_id.to_string(),
                path_segments: segs.to_vec(),
            };
            conn.object_server().at(path.as_str(), obj).await?;
            objects.insert(path.clone());
            debug!(path, "Mounted D-Bus projection object");
        }
    }

    Ok(())
}

/// Read a plugin's projection from shm and derive all D-Bus object paths.
fn read_and_derive_paths(plugin_id: &str) -> Option<Vec<Vec<String>>> {
    let bytes = op_core::projection_shm::read_projection_bytes(plugin_id)?;
    let value: serde_json::Value = serde_json::from_slice(&bytes).ok()?;
    // Derive paths from the `data` field if present (composite shm format).
    let root = value.get("data").unwrap_or(&value);
    Some(derive_paths_from_state(root))
}

/// Derive all D-Bus object paths from a plugin's state JSON.
fn derive_paths_from_state(value: &serde_json::Value) -> Vec<Vec<String>> {
    let mut paths = vec![Vec::new()]; // root (plugin root)
    derive_paths_recursive(value, &mut Vec::new(), &mut paths);
    paths
}

fn derive_paths_recursive(
    value: &serde_json::Value,
    current: &mut Vec<String>,
    paths: &mut Vec<Vec<String>>,
) {
    match value {
        serde_json::Value::Object(map) => {
            if !current.is_empty() {
                paths.push(current.clone());
            }
            for (key, child) in map {
                // Skip underscore-prefixed keys (metadata fields like
                // `_introspection`) — they don't create child D-Bus objects.
                if key.starts_with('_') {
                    continue;
                }
                if child.is_object() || child.is_array() {
                    current.push(key.clone());
                    derive_paths_recursive(child, current, paths);
                    current.pop();
                }
            }
        }
        serde_json::Value::Array(arr) => {
            if !current.is_empty() {
                paths.push(current.clone());
            }
            for (idx, child) in arr.iter().enumerate() {
                if child.is_object() || child.is_array() {
                    let segment = ["id", "name", "label", "key", "path", "domain", "host"]
                        .iter()
                        .find_map(|&field| child.get(field).and_then(|v| v.as_str()))
                        .map(|s| s.replace(['/', ' ', ':'], "_"))
                        .unwrap_or_else(|| idx.to_string());
                    current.push(segment);
                    derive_paths_recursive(child, current, paths);
                    current.pop();
                }
            }
        }
        _ => {}
    }
}

/// Manages the set of D-Bus objects served for all projections.
///
/// Each object reads its data 1:1 from the shm projection layer on every
/// property access. The server only tracks which paths are mounted (for
/// mount/unmount lifecycle); it holds no data copies.
pub struct ProjectionDbusServer {
    conn: Connection,
    /// Mounted object paths (shared with ProjectionRoot for refresh())
    objects: Arc<Mutex<HashSet<String>>>,
}

impl ProjectionDbusServer {
    pub async fn new() -> Result<Self> {
        let objects = Arc::new(Mutex::new(HashSet::new()));
        let root = ProjectionRoot {
            objects: objects.clone(),
        };

        let conn = match std::env::var("OP_DBUS_PROJECTION_BUS")
            .unwrap_or_else(|_| "system".to_string())
            .as_str()
        {
            "session" => {
                Builder::session()?
                    .serve_at("/org/opdbus/v1/plugins", root)?
                    .name(op_plugins::canonical::BASE_SERVICE_NAME)?
                    .build()
                    .await?
            }
            _ => {
                Builder::system()?
                    .serve_at("/org/opdbus/v1/plugins", root)?
                    .name(op_plugins::canonical::BASE_SERVICE_NAME)?
                    .build()
                    .await?
            }
        };

        mount_unix_socket_methods(&conn).await;

        info!(
            service = op_plugins::canonical::BASE_SERVICE_NAME,
            "D-Bus plugin projection connection established"
        );

        Ok(Self { conn, objects })
    }

    pub async fn new_session() -> Result<Self> {
        let objects = Arc::new(Mutex::new(HashSet::new()));
        let root = ProjectionRoot {
            objects: objects.clone(),
        };

        let conn = Builder::session()?
            .serve_at("/org/opdbus/v1/plugins", root)?
            .name(op_plugins::canonical::BASE_SERVICE_NAME)?
            .build()
            .await?;

        mount_unix_socket_methods(&conn).await;

        info!(
            service = op_plugins::canonical::BASE_SERVICE_NAME,
            "D-Bus session plugin projection connection established"
        );

        Ok(Self { conn, objects })
    }

    /// Sync the D-Bus tree from shm. Mounts new objects, unmounts stale ones.
    /// Called on startup. At runtime, the `refresh()` D-Bus method does the same.
    pub async fn sync_from_shm(&self) -> Result<()> {
        let mut objects = self.objects.lock().await;
        sync_all_from_shm(&self.conn, &mut objects).await
    }

    /// Ensure all known plugins have at least a root object mounted, even if
    /// no shm data exists yet (no mutations). Plugins with shm data get their
    /// full derived tree; plugins without shm get just the root (data returns `{}`).
    pub async fn seed_plugin_roots(&self, plugin_ids: &[String]) -> Result<()> {
        let mut objects = self.objects.lock().await;
        for plugin_id in plugin_ids {
            // If shm has data, sync the full derived tree.
            if let Some(paths) = read_and_derive_paths(plugin_id) {
                sync_plugin_paths(&self.conn, &mut objects, plugin_id, &paths).await?;
            } else {
                // No shm data — mount just the root so the plugin appears in the tree.
                let root_path = build_projected_path(plugin_id, &[]);
                if !objects.contains(&root_path) {
                    let obj = ProjectedObject {
                        plugin_id: plugin_id.to_string(),
                        path_segments: Vec::new(),
                    };
                    self.conn
                        .object_server()
                        .at(root_path.as_str(), obj)
                        .await?;
                    objects.insert(root_path.clone());
                    debug!(path = root_path, "Seeded plugin root (no shm data yet)");
                }
            }
        }
        Ok(())
    }

    /// Sync a single plugin's D-Bus objects to match the derived paths.
    pub async fn sync_plugin(&mut self, plugin_id: &str, paths: &[Vec<String>]) -> Result<()> {
        let mut objects = self.objects.lock().await;
        sync_plugin_paths(&self.conn, &mut objects, plugin_id, paths).await
    }

    pub async fn object_count(&self) -> usize {
        self.objects.lock().await.len()
    }

    /// Mount a projection as a D-Bus object (or emit `updated` if already mounted).
    pub async fn upsert(&mut self, plugin_id: &str, path_segments: &[String]) -> Result<()> {
        let path = build_projected_path(plugin_id, path_segments);

        {
            let mut objects = self.objects.lock().await;
            if !objects.contains(&path) {
                let obj = ProjectedObject {
                    plugin_id: plugin_id.to_string(),
                    path_segments: path_segments.to_vec(),
                };
                self.conn.object_server().at(path.as_str(), obj).await?;
                objects.insert(path.clone());
                debug!(path, "Mounted D-Bus projection object");
            }
        }

        // Emit updated signal with current shm data (push notification).
        let data = read_projected_data(plugin_id, path_segments);
        let iface_ref = self
            .conn
            .object_server()
            .interface::<_, ProjectedObject>(path.as_str())
            .await?;
        ProjectedObject::updated(iface_ref.signal_emitter(), &data).await?;

        debug!(path, "Updated D-Bus projection object");
        Ok(())
    }

    /// Remove a projection's D-Bus object.
    pub async fn remove(&mut self, plugin_id: &str, path_segments: &[String]) -> Result<()> {
        let path = build_projected_path(plugin_id, path_segments);
        let mut objects = self.objects.lock().await;
        if objects.remove(&path) {
            self.conn
                .object_server()
                .remove::<ProjectedObject, _>(path.as_str())
                .await?;
            info!(path, "Removed D-Bus projection object");
        }
        Ok(())
    }

    pub fn connection(&self) -> &Connection {
        &self.conn
    }
}

#[cfg(test)]
mod tests {
    use super::projection_path;

    #[test]
    fn projects_plugin_roots_under_canonical_plugin_path() {
        assert_eq!(
            projection_path("mail_server", "mail_server"),
            "/org/opdbus/v1/plugins/mail_server"
        );
        assert_eq!(
            projection_path("ovsdb_bridge", "ovsdb_bridge"),
            "/org/opdbus/v1/plugins/ovsdb_bridge"
        );
    }

    #[test]
    fn projects_nested_objects_under_owning_plugin() {
        assert_eq!(
            projection_path("plugin.object", "wireguard:/interfaces/0/peers"),
            "/org/opdbus/v1/plugins/wireguard/interfaces/0/peers"
        );
    }
}
